window.HOEREN_TESTS[54] = {"id":"beim-fussball","name":"Beim Fußball","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Fans: Das Spiel Bayern München gegen Dortmund findet heute Abend statt, aber nicht im Allianz Stadium und nicht im Stadtpark, sondern im kleineren Olympia-Stadion. Wegen der Bauarbeiten. Die Tickets bleiben gültig. Beginn 20 Uhr 30 wie geplant. Wir freuen uns auf alle Fans und auf eine tolle Stimmung im Stadion!","gender":"f","q":"Wo findet das Spiel statt?","opts":["Allianz Stadium.","Olympia-Stadion.","Stadtpark."],"correct":1},{"transcript":"Hallo Markus, hier ist Tom. Ich habe zwei Tickets für das Spiel am Samstag bekommen, ein Geschenk vom Chef. Ich will sie nicht verkaufen. Kommst du mit? Beste Plätze, direkt am Spielfeld. Treffen 14 Uhr beim Bahnhof. Sag bitte zu oder ab, sonst kann ich Anna einladen. Bis bald und hoffentlich bis Samstag!","gender":"m","q":"Was möchte Tom?","opts":["Tickets verkaufen.","Anna einladen.","Markus einladen."],"correct":2},{"transcript":"Achtung Fans: Aus Sicherheits-Gründen sind keine Flaschen im Stadion erlaubt. Kleine Taschen ja, die dürfen Sie mitnehmen. Fahnen ohne lange Stöcke sind auch okay. Große Rucksäcke nein. Bitte nicht zu früh kommen, der Eingang öffnet 90 Minuten vor Spiel-Beginn. Vielen Dank und viel Spaß beim Spiel!","gender":"m","q":"Was ist nicht erlaubt?","opts":["Kleine Taschen.","Fahnen.","Flaschen."],"correct":2},{"transcript":"Hi Lisa, hier ist Anna. Pass auf, mein Mann und ich gehen morgen zum Fußball-Spiel. Ich will dich nicht zum Spiel einladen und ich will auch kein Geld leihen. Hast du Lust, auf unsere Kinder aufzupassen, zwei Stunden nur, von 19 bis 21 Uhr? Sie sind brav und schlafen früh. Wir zahlen gerne. Ruf bitte zurück!","gender":"f","q":"Was möchte Anna?","opts":["Babysitter-Hilfe.","Lisa zum Spiel einladen.","Geld leihen."],"correct":0},{"transcript":"Liebe Vereinsmitglieder: Unser Verein FC Sonnenblume bleibt derselbe Verein in derselben Liga. Neu ist eine neue Trainerin, Anna Schmidt. Sie kommt aus der Frauen-Bundesliga und ist sehr erfahren. Das erste Training mit ihr ist am Montag um 18 Uhr. Bitte alle kommen und sich vorstellen. Wir freuen uns auf eine neue Spielphilosophie!","gender":"f","q":"Was ist neu?","opts":["Neuer Verein.","Neue Trainerin.","Neue Liga."],"correct":1}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer mag welchen Verein? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Heute Abend läuft das große Spiel und mein Schal liegt bereit."},{"speaker":"Lisa","gender":"f","text":"Ich bin auch bereit. In unserer Küche hängen schon drei Fahnen."},{"speaker":"Lukas","gender":"m","text":"Ich halte zu Bayern München. Seit der Schulzeit klebt das Wappen an meiner Tür."},{"speaker":"Lisa","gender":"f","text":"Bei mir ist es Dortmund. Gelb und schwarz trage ich sogar im Sommer."},{"speaker":"Lukas","gender":"m","text":"Mag jemand von uns Köln?"},{"speaker":"Lisa","gender":"f","text":"Nein. Köln ist bei uns nicht dabei."},{"speaker":"Lukas","gender":"m","text":"Tom kommt aus dem Westen und bleibt seinem Verein treu."},{"speaker":"Lisa","gender":"f","text":"Tom mag Schalke 04. Sein Schal ist blau und weiß wie der Himmel."},{"speaker":"Lukas","gender":"m","text":"Im Norden an der Elbe wohnt jemand aus unserer Runde."},{"speaker":"Lisa","gender":"f","text":"Sara hält zum Hamburger SV. Zweimal im Jahr fährt sie ins Stadion."},{"speaker":"Lukas","gender":"m","text":"Mag jemand Frankfurt am Main?"},{"speaker":"Lisa","gender":"f","text":"Nein. Frankfurt mögen wir auch nicht. Die Spieler kennt hier keiner."},{"speaker":"Lukas","gender":"m","text":"Tim redet ständig von einem Stadion an der Weser."},{"speaker":"Lisa","gender":"f","text":"Tim mag Werder Bremen. Grün und weiß hängen als Fahnen bei ihm in der Küche."},{"speaker":"Lukas","gender":"m","text":"Dann schauen wir heute in zwei verschiedenen Trikots."},{"speaker":"Lisa","gender":"f","text":"Ich stelle eine Schüssel mit Salzstangen auf den Tisch."}],"options":[{"letter":"a","text":"Dortmund"},{"letter":"b","text":"Werder Bremen"},{"letter":"c","text":"Hertha Berlin"},{"letter":"d","text":"Köln"},{"letter":"e","text":"Schalke 04"},{"letter":"f","text":"RB Leipzig"},{"letter":"g","text":"Hamburger SV"},{"letter":"h","text":"Frankfurt"},{"letter":"i","text":"Bayern München"}],"items":[{"person":"Lukas","correct":"i"},{"person":"Lisa","correct":"a"},{"person":"Tom","correct":"e"},{"person":"Sara","correct":"g"},{"person":"Tim","correct":"b"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Kunde","gender":"m","text":"Guten Tag, zwei Tickets bitte für das Heimspiel am Samstag. Was haben Sie noch?"},{"speaker":"Verkäuferin","gender":"f","text":"Stehplatz für 20 Euro, Mittel-Sitzplatz für 40, VIP-Platz für 120. Welche Kategorie?"},{"speaker":"Kunde","gender":"m","text":"VIP ist zu teuer, Stehplatz ist mir zu voll. Lieber Mittel, 40 Euro."},{"speaker":"Verkäuferin","gender":"f","text":"Stehplatz nur 20 Euro, VIP ist fast voll. Mittel-Sitzplatz haben wir noch, Reihe 12."},{"speaker":"Kunde","gender":"m","text":"Ich bleibe bei Mittel-Sitzplatz. Zwei Karten bitte, danke!"}],"q":"Was kauft der Kunde?","opts":["Stehplatz.","VIP-Platz.","Mittel-Sitzplatz."],"correct":2},{"lines":[{"speaker":"Trainer","gender":"m","text":"Lukas, du bist verspätet! Das Training hat schon vor zehn Minuten begonnen."},{"speaker":"Lukas","gender":"m","text":"Sorry Trainer, der Bus hatte Verspätung. Es tut mir wirklich leid."},{"speaker":"Trainer","gender":"m","text":"Du bist Stürmer, nicht Torwart und nicht Verteidiger. Du musst pünktlich da sein."},{"speaker":"Lukas","gender":"m","text":"Versprochen, nie wieder. Heute spiele ich Stürmer wie immer, ich gebe alles."},{"speaker":"Trainer","gender":"m","text":"Gut, dann schnell umziehen. Die anderen warten schon auf dem Platz."}],"q":"Welche Position hat Lukas?","opts":["Stürmer.","Torwart.","Verteidiger."],"correct":0},{"lines":[{"speaker":"Sohn","gender":"m","text":"Papa, ich brauche neue Fußballschuhe! Meine alten tun am Fuß weh."},{"speaker":"Vater","gender":"m","text":"Welche Marke willst du, Adidas, Nike oder Puma? Es gibt viele im Angebot."},{"speaker":"Sohn","gender":"m","text":"Adidas oder Nike, egal. Puma mag ich nicht so, die Form gefällt mir nicht."},{"speaker":"Vater","gender":"m","text":"Adidas haben heute eine Aktion, nur 60 Euro. Nike ist teurer, 80 Euro."},{"speaker":"Sohn","gender":"m","text":"Dann Adidas bitte. Danke Papa, die ziehe ich schon am Samstag an!"}],"q":"Welche Marke?","opts":["Nike.","Adidas.","Puma."],"correct":1},{"lines":[{"speaker":"Junge1","gender":"m","text":"Hey, wer hat gewonnen, Bayern oder Dortmund? Oder unentschieden?"},{"speaker":"Junge2","gender":"m","text":"Dortmund 2 zu 1, nicht Bayern und nicht unentschieden. Ein enges Spiel."},{"speaker":"Junge1","gender":"m","text":"Krass! Wer hat die Tore geschossen, weißt du das?"},{"speaker":"Junge2","gender":"m","text":"Beide Tore von Reus. Bayern hat nur eins bekommen, ganz am Ende."},{"speaker":"Junge1","gender":"m","text":"Wow, dann hat Dortmund verdient gewonnen. Nächstes Mal schaue ich mit!"}],"q":"Wer hat gewonnen?","opts":["Bayern.","Unentschieden.","Dortmund."],"correct":2},{"lines":[{"speaker":"Frau","gender":"f","text":"Mein Mann ist heute Abend zum Fußball, deshalb bin ich allein zu Hause."},{"speaker":"Nachbarin","gender":"f","text":"Ist er im Stadion, zu Hause vor dem Fernseher, oder im Restaurant mit Kollegen?"},{"speaker":"Frau","gender":"f","text":"Im Stadion, mit Freunden. Nicht zu Hause und nicht im Restaurant."},{"speaker":"Nachbarin","gender":"f","text":"Du auch mit ins Stadion? Oder bleibst du lieber hier?"},{"speaker":"Frau","gender":"f","text":"Nein, ich bin froh allein zu Hause. Fußball im Stadion ist nichts für mich."}],"q":"Wo ist der Mann?","opts":["Im Stadion.","Zu Hause.","Im Restaurant."],"correct":0}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Herrn Müller, einem ehemaligen Fußball-Profi. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporterin","gender":"f","text":"Herr Müller, Sie waren 15 Jahre Profi-Fußballer. Wie haben Sie damit angefangen?"},{"speaker":"Müller","gender":"m","text":"Schon mit 5 Jahren bin ich im Hof gekickt — mein Vater hat mit mir geübt. Mit 10 in Verein, mit 14 in Nachwuchs eines großen Clubs. Mit 18 erster Profi-Vertrag. Glück, Talent, harte Arbeit — alles zusammen."},{"speaker":"Reporterin","gender":"f","text":"Wie war das Leben als Profi?"},{"speaker":"Müller","gender":"m","text":"Hart, aber spannend. Tägliches Training, Spiele am Wochenende, oft auf Reisen. Wenig Privatleben. Aber das Geld war gut, das Publikum hat uns geliebt — wenn alles lief. Bei Verletzungen oder schlechten Spielen ganz anders."},{"speaker":"Reporterin","gender":"f","text":"Hatten Sie viele Verletzungen?"},{"speaker":"Müller","gender":"m","text":"Genug. Knie-Operation einmal, Knöchel mehrmals. Eine ganze Saison verpasst wegen Kreuzband-Riss. Schmerz war nicht das Schlimmste — Angst, dass Karriere zu Ende ist. Aber das Comeback hat geklappt."},{"speaker":"Reporterin","gender":"f","text":"Was machen Sie heute?"},{"speaker":"Müller","gender":"m","text":"Ich bin Trainer, bei Jugend-Mannschaft eines kleinen Vereins. Auch TV-Kommentator manchmal, bei großen Spielen. Schreibe für eine Sport-Zeitung. Genug zu tun. Familie auch wichtig — endlich Zeit für Kinder."},{"speaker":"Reporterin","gender":"f","text":"Was raten Sie jungen Spielern?"},{"speaker":"Müller","gender":"m","text":"Schule nicht vergessen! Karriere endet schnell, mit 35 ist Schluss. Brauchst Plan B. Auch: keine Drogen, kein Alkohol — viele junge Profis zerstören sich selbst. Geld macht stark, aber auch dumm. Klare Köpfe behalten."}],"items":[{"q":"Herr Müllers Vater hat ihm beim Fußball geholfen.","correct":"ja"},{"q":"Das Leben als Profi ist immer leicht und glücklich.","correct":"nein"},{"q":"Er hatte mehrere Verletzungen während seiner Karriere.","correct":"ja"},{"q":"Heute arbeitet er gar nicht im Fußball-Bereich.","correct":"nein"},{"q":"Er rät jungen Spielern, die Schule zu vernachlässigen.","correct":"nein"}]}]};
